def read_json(path: Path) -> Any:
    with open(long_path(path), "r", encoding="utf-8") as handle:
        return json.load(handle)


def long_path(path: Path) -> str:
    path_text = str(path)
    if len(path_text) >= 240 and not path_text.startswith("\\\\?\\"):
        return "\\\\?\\" + path_text
    return path_text


def path_exists(path: Path) -> bool:
    return os.path.exists(long_path(path))


def parse_jsonl(path: Path) -> int:
    count = 0
    with open(long_path(path), "r", encoding="utf-8", errors="replace") as handle:
        for line_no, line in enumerate(handle, 1):
            if not line.strip():
                continue
            try:
                json.loads(line)
            except json.JSONDecodeError as exc:
                raise AssertionError(f"{path}:{line_no} JSON parse error: {exc}") from exc
            count += 1
    return count


def read_jsonl_rows(path: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    with open(long_path(path), "r", encoding="utf-8", errors="replace") as handle:
        for line_no, line in enumerate(handle, 1):
            if not line.strip():
                continue
            try:
                payload = json.loads(line)
            except json.JSONDecodeError as exc:
                raise AssertionError(f"{path}:{line_no} JSON parse error: {exc}") from exc
            if not isinstance(payload, dict):
                raise AssertionError(f"{path}:{line_no} JSONL row is not an object")
            rows.append(payload)
    return rows


def safe_flags_ok(payload: dict[str, Any]) -> bool:
    flags = payload.get("safe_flags") or {}
    no_promotion = (
        flags.get("NO_PROMOTION_VERDICT") is True
        or flags.get("promotion_verdict") == "NO_PROMOTION_VERDICT"
    )
    return (
        no_promotion
        and flags.get("validation_safe") is False
        and flags.get("outcome_review_opened") is False
        and flags.get("live_effect") is False
    )


def find_forbidden_keys(payload: Any, forbidden: set[str]) -> set[str]:
    found: set[str] = set()
    if isinstance(payload, dict):
        for key, value in payload.items():
            if key in forbidden:
                found.add(key)
            found.update(find_forbidden_keys(value, forbidden))
    elif isinstance(payload, list):
        for item in payload:
            found.update(find_forbidden_keys(item, forbidden))
    return found


def validate_prompt() -> dict[str, Any]:
    cmd = [sys.executable, "scripts/validate_goal_prompt_hardening.py", str(PROMPT)]
    completed = subprocess.run(cmd, cwd=REPO, capture_output=True, text=True)
    return {
        "command": " ".join(cmd),
        "returncode": completed.returncode,
        "stdout": completed.stdout,
        "stderr": completed.stderr,
        "ok": completed.returncode == 0 and "overall_ok=True" in completed.stdout,
    }


def main() -> int:
    issues: list[str] = []
    jsonl_counts: dict[str, int] = {}
    json_counts: dict[str, Any] = {}

    prompt_result = validate_prompt()
    if not prompt_result["ok"]:
        issues.append("prompt_hardening_validation_failed")

    for path in SAFE_JSON_FILES:
        if not path_exists(path):
            issues.append(f"missing_json:{path.name}")
            continue
        payload = read_json(path)
        json_counts[path.name] = payload.get("counts")
        if not safe_flags_ok(payload):
            issues.append(f"safe_flags_not_closed:{path.name}")

    for path in JSONL_FILES:
        if not path_exists(path):
            issues.append(f"missing_jsonl:{path.name}")
            continue
        jsonl_counts[path.name] = parse_jsonl(path)

    for path in PY_FILES:
        if not path_exists(path):
            issues.append(f"missing_py:{path.name}")
            continue
        try:
            ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
        except SyntaxError as exc:
            issues.append(f"syntax_parse_failed:{path.name}:{exc}")

    shadow_result = read_json(ROUTE_DIR / "PARENT_SHADOW_MECHANICAL_EDGE_FACTORY_RESULT_2026-05-15.json")
    shadow_counts = shadow_result["counts"]
    expected_shadow = {
        "strategy_rollup_rows": "PARENT_SHADOW_MECHANICAL_STRATEGY_ROLLUP_2026-05-15.jsonl",
        "path_descriptor_rows": "PARENT_MARKET_BEHAVIOR_DESCRIPTOR_LEDGER_2026-05-15.jsonl",
        "failure_intelligence_rows": "PARENT_FAILURE_INTELLIGENCE_LEDGER_2026-05-15.jsonl",
        "hypothesis_rows": "PARENT_CHALLENGER_HYPOTHESIS_LEDGER_2026-05-15.jsonl",
    }
    for count_key, filename in expected_shadow.items():
        if shadow_counts[count_key] != jsonl_counts.get(filename):
            issues.append(f"shadow_count_mismatch:{count_key}")

    nofill_result = read_json(ROUTE_DIR / "NOFILL_ENTRY_GEOMETRY_DESIGN_RESULT_2026-05-15.json")
    nofill_counts = nofill_result["counts"]
    expected_nofill = {
        "nofill_tp_area_rows": "NOFILL_ENTRY_GEOMETRY_SOURCE_ROWS_2026-05-15.jsonl",
        "nofill_group_rows": "NOFILL_ENTRY_GEOMETRY_GROUP_LEDGER_2026-05-15.jsonl",
        "path_context_rows": "NOFILL_ENTRY_GEOMETRY_PATH_CONTEXT_LEDGER_2026-05-15.jsonl",
        "branch_spec_rows": "NOFILL_ENTRY_GEOMETRY_BRANCH_SPECS_2026-05-15.jsonl",
        "capture_requirement_rows": "NOFILL_ENTRY_GEOMETRY_CAPTURE_REQUIREMENTS_2026-05-15.jsonl",
    }
    for count_key, filename in expected_nofill.items():
        if nofill_counts[count_key] != jsonl_counts.get(filename):
            issues.append(f"nofill_count_mismatch:{count_key}")

    nofill_challenger_result = read_json(ROUTE_DIR / "NOFILL_ENTRY_GEOMETRY_CHALLENGER_RESULT_2026-05-16.json")
    nofill_challenger_counts = nofill_challenger_result["counts"]
    expected_nofill_challenger = {
        "latest_candidate_denominator_rows": "NOFILL_ENTRY_GEOMETRY_CHALLENGER_INPUT_JOIN_2026-05-16.jsonl",
        "branch_rows": "NOFILL_ENTRY_GEOMETRY_CHALLENGER_BRANCH_PACKET_2026-05-16.jsonl",
        "readiness_rows": "NOFILL_ENTRY_GEOMETRY_CHALLENGER_READINESS_LEDGER_2026-05-16.jsonl",
        "denominator_rows": "NOFILL_ENTRY_GEOMETRY_CHALLENGER_DENOMINATOR_LEDGER_2026-05-16.jsonl",
        "bucket_rows": "NOFILL_ENTRY_GEOMETRY_CHALLENGER_BUCKET_LEDGER_2026-05-16.jsonl",
        "question_rows": "NOFILL_ENTRY_GEOMETRY_CHALLENGER_QUESTION_LEDGER_2026-05-16.jsonl",
    }
    for count_key, filename in expected_nofill_challenger.items():
        if nofill_challenger_counts[count_key] != jsonl_counts.get(filename):
            issues.append(f"nofill_challenger_count_mismatch:{count_key}")
    if nofill_challenger_counts["latest_candidate_denominator_rows"] != nofill_challenger_counts["denominator_rows"]:
        issues.append("nofill_challenger_denominator_not_preserved")
    if nofill_challenger_counts["latest_candidate_denominator_rows"] != nofill_counts["latest_candidate_path_rows"]:
        issues.append("nofill_challenger_design_denominator_mismatch")
    if nofill_challenger_counts["nofill_tp_area_rows"] != nofill_counts["nofill_tp_area_rows"]:
        issues.append("nofill_challenger_design_nofill_mismatch")
    if nofill_challenger_counts["branch_rows"] != nofill_challenger_counts["nofill_tp_area_rows"] * 5:
        issues.append("nofill_challenger_branch_expansion_mismatch")
    if nofill_challenger_counts["readiness_rows"] != nofill_challenger_counts["branch_rows"]:
        issues.append("nofill_challenger_readiness_branch_mismatch")
    if sum(nofill_challenger_result.get("readiness_status_counts", {}).values()) != nofill_challenger_counts["readiness_rows"]:
        issues.append("nofill_challenger_readiness_status_sum_mismatch")
    if sum(nofill_challenger_result.get("path_label_counts", {}).values()) != nofill_challenger_counts["latest_candidate_denominator_rows"]:
        issues.append("nofill_challenger_path_label_sum_mismatch")
    if nofill_challenger_counts["source_manifest_rows"] != len(nofill_challenger_result.get("source_manifest", [])):
        issues.append("nofill_challenger_source_manifest_count_mismatch")

    nofill_challenger_files = {
        "input": ROUTE_DIR / "NOFILL_ENTRY_GEOMETRY_CHALLENGER_INPUT_JOIN_2026-05-16.jsonl",
        "branch": ROUTE_DIR / "NOFILL_ENTRY_GEOMETRY_CHALLENGER_BRANCH_PACKET_2026-05-16.jsonl",
        "readiness": ROUTE_DIR / "NOFILL_ENTRY_GEOMETRY_CHALLENGER_READINESS_LEDGER_2026-05-16.jsonl",
        "denominator": ROUTE_DIR / "NOFILL_ENTRY_GEOMETRY_CHALLENGER_DENOMINATOR_LEDGER_2026-05-16.jsonl",
        "bucket": ROUTE_DIR / "NOFILL_ENTRY_GEOMETRY_CHALLENGER_BUCKET_LEDGER_2026-05-16.jsonl",
        "question": ROUTE_DIR / "NOFILL_ENTRY_GEOMETRY_CHALLENGER_QUESTION_LEDGER_2026-05-16.jsonl",
    }
    nofill_challenger_rows = {
        name: read_jsonl_rows(path)
        for name, path in nofill_challenger_files.items()
        if path_exists(path)
    }
    nofill_forbidden_keys = {
        "actual_r",
        "broker_result",
        "win_loss",
        "account_history",
        "deal_ticket",
        "order_ticket",
        "pnl",
        "profit",
        "loss",
        "expectancy",
        "win_rate",
        "live_readiness",
    }
    source_manifest_hash = nofill_challenger_result.get("source_manifest_hash")
    hash_bound_row_groups = {"input", "branch", "readiness", "denominator"}
    for group_name, rows in nofill_challenger_rows.items():
        for row_index, row in enumerate(rows, 1):
            if not safe_flags_ok(row):
                issues.append(f"nofill_challenger_row_safe_flags_open:{group_name}:{row_index}")
                break
            forbidden = find_forbidden_keys(row, nofill_forbidden_keys)
            if forbidden:
                issues.append(f"nofill_challenger_forbidden_keys:{group_name}:{row_index}:{','.join(sorted(forbidden))}")
                break
            if group_name in hash_bound_row_groups:
                if row.get("source_manifest_hash") != source_manifest_hash:
                    issues.append(f"nofill_challenger_source_manifest_hash_missing:{group_name}:{row_index}")
                    break
                if row.get("source_file_hash_status") != "HASHED_SOURCE_MANIFEST":
                    issues.append(f"nofill_challenger_source_file_hash_status_missing:{group_name}:{row_index}")
                    break

    input_rows = nofill_challenger_rows.get("input", [])
    branch_rows = nofill_challenger_rows.get("branch", [])
    readiness_rows = nofill_challenger_rows.get("readiness", [])
    denominator_rows = nofill_challenger_rows.get("denominator", [])
    nofill_candidate_ids = {
        row["candidate_id"]
        for row in input_rows
        if row.get("is_nofill_tp_area") is True
    }
    if len(nofill_candidate_ids) != nofill_challenger_counts["nofill_tp_area_rows"]:
        issues.append("nofill_challenger_nofill_id_count_mismatch")
    branch_candidate_ids = {row.get("candidate_id") for row in branch_rows}
    if not branch_candidate_ids.issubset(nofill_candidate_ids):
        issues.append("nofill_challenger_branch_candidate_outside_nofill_set")
    branch_id_counts: dict[str, int] = {}
    for row in branch_rows:
        branch_id = row.get("branch_id")
        if branch_id:
            branch_id_counts[branch_id] = branch_id_counts.get(branch_id, 0) + 1
    if len(branch_id_counts) != nofill_challenger_counts["branch_rows"] or any(count != 1 for count in branch_id_counts.values()):
        issues.append("nofill_challenger_branch_id_not_unique")
    branches_by_candidate: dict[str, int] = {}
    for row in branch_rows:
        candidate_id = row.get("candidate_id")
        if candidate_id:
            branches_by_candidate[candidate_id] = branches_by_candidate.get(candidate_id, 0) + 1
    if any(branches_by_candidate.get(candidate_id) != 5 for candidate_id in nofill_candidate_ids):
        issues.append("nofill_challenger_candidate_branch_count_not_five")
    readiness_branch_ids = {row.get("branch_id") for row in readiness_rows}
    if readiness_branch_ids != set(branch_id_counts):
        issues.append("nofill_challenger_readiness_branch_id_set_mismatch")
    denominator_candidate_ids = {row.get("candidate_id") for row in denominator_rows}
    input_candidate_ids = {row.get("candidate_id") for row in input_rows}
    if denominator_candidate_ids != input_candidate_ids:
        issues.append("nofill_challenger_denominator_input_id_set_mismatch")

    nofill_repair_result = read_json(ROUTE_DIR / "NOFILL_ENTRY_GEOMETRY_REPAIR_PROXY_RESULT_2026-05-16.json")
    nofill_repair_counts = nofill_repair_result["counts"]
    expected_nofill_repair = {
        "candidate_proxy_rows": "NOFILL_ENTRY_GEOMETRY_REPAIR_PROXY_CANDIDATE_LEDGER_2026-05-16.jsonl",
        "branch_proxy_rows": "NOFILL_ENTRY_GEOMETRY_REPAIR_PROXY_BRANCH_LEDGER_2026-05-16.jsonl",
        "spread_proxy_symbol_rows": "NOFILL_ENTRY_GEOMETRY_REPAIR_PROXY_SPREAD_LEDGER_2026-05-16.jsonl",
        "bucket_rows": "NOFILL_ENTRY_GEOMETRY_REPAIR_PROXY_BUCKET_LEDGER_2026-05-16.jsonl",
        "question_rows": "NOFILL_ENTRY_GEOMETRY_REPAIR_PROXY_QUESTION_LEDGER_2026-05-16.jsonl",
    }
    for count_key, filename in expected_nofill_repair.items():
        if nofill_repair_counts[count_key] != jsonl_counts.get(filename):
            issues.append(f"nofill_repair_proxy_count_mismatch:{count_key}")
    if nofill_repair_counts["branch_proxy_rows"] != nofill_challenger_counts["branch_rows"]:
        issues.append("nofill_repair_proxy_branch_scope_mismatch")
