    def _detail_stat(rows: list[dict[str, Any]], key: str, prefix: str) -> dict[str, float | None]:
        values = [float(row.get(key)) for row in rows if row.get(key) is not None]
        if not values:
            return {f"{prefix}_min": None, f"{prefix}_mean": None, f"{prefix}_max": None}
        return {
            f"{prefix}_min": round(min(values), 6),
            f"{prefix}_mean": round(sum(values) / len(values), 6),
            f"{prefix}_max": round(max(values), 6),
        }
